{Atleast one Booking.Transaction.type == FullPayment,
If Booking.Transaction.type == FullPayment and status == Completed and Booking.status == PaymentPending then Booking.status = Confirmed
If no Booking.Transaction.type == FullPayment and status == Completed then Booking.status != Confirmed}

{Conversation can't have a Booking and a Listing,
{f Conversation.Booking != NULL then Conversation.Host == Booking.Listing.Host,
If Conversation.Listing != NULL then Conversation.Host == Listing.Host}

{if type == 'AdminNotice' then (AdminNotification NN and admin NN) else (AdminNotification NULL AND admin NN),
if type in ('BookingConfirmed', 'BookingCanceled', 'Remainder') then Booking NN else Booking NULL,
if type == 'ReviewLeft' then Review NN else Review NULL,
if type == 'MessageReceived' then Message NN else Message NULL,
if type == 'PaymentReceived' then Transaction NN else Transaction NULL}
